DIALOGS = [
[anyone, "cp_crusader_1", [], "Ah, so our enemies finally had the guts to reveal themselves ! Hear me out, {playername} ! I am {s29}, chosen champion of Marsus, scourge of pagans and barbarians alike ! You and every {s32} are a nation of cowards ! Offsprings of heathen subhumans ! I was among the first to lay your castles low back in your homeland, yet you miserable bunch of weaklings didn't even have the courage to fall dead beside your brethren ! Now behold, for not even in Calradia are you safe from the might of Marsus ! And don't even expect protection from {s33} ! Your religion and deities are just as worthless and pathetic as every other aspect of your existence ! Tremble in terror, for the day of your last judgement is nigh !", "cp_crusader_2", [] ],
]
